func:
if (Number(flow.get('envases_http_busy_until') || 0) > Date.now()) {
    return [null, { payload: { status: 'SKIPPED_BUSY', message: 'Solicitud anterior pendiente' } }];
}

const base = env.get('DISAL_API_BASE_URL');
const key = env.get('DISAL_ENVASES_INTEGRATION_KEY');

if (!base || !key) {
    return [null, { payload: { status: 'CONFIG_ERROR', message: 'Falta DISAL_API_BASE_URL o DISAL_ENVASES_INTEGRATION_KEY' } }];
}

if (!msg.payload || !Array.isArray(msg.payload.maquinas)) {
    return [null, { payload: { status: 'INVALID_SUMMARY', message: 'msg.payload.maquinas no es un arreglo' } }];
}

// El normalizador agrega marcadores SIN_FILA_SQL sin cms_timestamp.
// La API acepta lotes parciales, pero cada lectura enviada debe tener timestamp ISO válido.
const maquinas = msg.payload.maquinas.filter((maquina) =>
    maquina &&
    typeof maquina.machine_ip === 'string' &&
    typeof maquina.cms_timestamp === 'string' &&
    Number.isFinite(Date.parse(maquina.cms_timestamp))
);

if (maquinas.length === 0) {
    return [null, { payload: { status: 'NO_VALID_READINGS', received: msg.payload.maquinas.length, sent: 0 } }];
}

flow.set('envases_http_busy_until', Date.now() + 25000);

msg.method = 'POST';
msg.url = base.replace(/\/$/, '') + '/plants/ENVASES/telemetry/injection-machines';
msg.headers = {
    'content-type': 'application/json',
    'x-node-red-key': key
};
msg.payload = {
    ...msg.payload,
    source: 'NODE_RED_ENVASES',
    schemaVersion: 1,
    maquinas
};
msg.envasesBody = msg.payload;
msg.envasesAttempt = 0;
msg.envasesMachineCount = maquinas.length;
return [msg, null];

const statusCode = Number(msg.statusCode || 0);
const attempt = Number(msg.envasesAttempt || 0);
const shouldRetry = statusCode === 0 || statusCode === 429 || statusCode >= 500;

if (shouldRetry && attempt < 2) {
    msg.envasesAttempt = attempt + 1;
    msg.payload = msg.envasesBody;
    msg.headers = {
        'content-type': 'application/json',
        'x-node-red-key': env.get('DISAL_ENVASES_INTEGRATION_KEY')
    };
    return [msg, null];
}

flow.set('envases_http_busy_until', 0);
return [null, {
    payload: {
        statusCode,
        attempts: attempt + 1,
        sent: msg.envasesMachineCount,
        accepted: msg.payload && msg.payload.accepted,
        rejected: msg.payload && msg.payload.rejected,
        ignored: msg.payload && msg.payload.ignored,
        error: statusCode >= 400 ? (msg.payload && msg.payload.message) || 'Respuesta HTTP no exitosa' : undefined
    }
}];

const attempt = Number(msg.envasesAttempt || 0);
if (attempt < 2) {
    msg.envasesAttempt = attempt + 1;
    msg.payload = msg.envasesBody;
    msg.headers = {
        'content-type': 'application/json',
        'x-node-red-key': env.get('DISAL_ENVASES_INTEGRATION_KEY')
    };
    return [msg, null];
}

flow.set('envases_http_busy_until', 0);
return [null, {
    payload: {
        status: 'HTTP_ERROR',
        attempts: attempt + 1,
        sent: msg.envasesMachineCount,
        message: String((msg.error && msg.error.message) || 'Error de red').slice(0, 180)
    }
}];
